def even_odd_count(num):
    num_str = str(abs(num))  # Convert to string after taking absolute value
    even_count = 0
    odd_count = 0

    for digit in num_str:
        if int(digit) % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    return (even_count, odd_count)

